plugins {
    id 'java'
}

group = 'order'
version = '0.1.0-SNAPSHOT'

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

repositories {
    mavenCentral()
}

dependencies {
    testImplementation 'org.junit.jupiter:junit-jupiter:5.11.4'
}

tasks.withType(JavaCompile).configureEach {
    options.encoding = 'UTF-8'
    options.release = 17
}

tasks.withType(Test).configureEach {
    useJUnitPlatform()
}

def businessPackages = ['order', 'payment', 'delivery', 'product'] as Set
def allowedDependencies = [
    order          : ['payment', 'delivery', 'product'] as Set,
    payment        : [] as Set,
    delivery       : [] as Set,
    product        : [] as Set,
    paymentadapter : ['payment'] as Set,
    deliveryadapter: ['delivery'] as Set,
    persistence    : ['order'] as Set
]

tasks.register('verifyPackageDependencies') {
    group = 'verification'
    description = 'Verifies the package dependency rules from docs/04-아키텍처-결정.md.'

    doLast {
        fileTree('src/main/java') {
            include '**/*.java'
        }.files.each { sourceFile ->
            def sourcePackage = (sourceFile.text =~ /(?m)^\s*package\s+([a-z]+)(?:\.|;)/).with { it.find() ? it.group(1) : null }
            if (!(sourcePackage in allowedDependencies.keySet())) {
                return
            }

            def imports = sourceFile.text.findAll(/(?m)^\s*import\s+(?:static\s+)?([a-z]+)(?:\.[\w.*]+)?\s*;/) { match, target -> target }
            imports.each { targetPackage ->
                if (targetPackage in allowedDependencies.keySet() &&
                    targetPackage != sourcePackage &&
                    !(targetPackage in allowedDependencies[sourcePackage])) {
                    throw new GradleException("Forbidden package dependency: ${sourcePackage} -> ${targetPackage} in ${sourceFile}")
                }
            }
        }
    }
}

tasks.named('check') {
    dependsOn tasks.named('verifyPackageDependencies')
}
